  "check_code": "import sqlite3
from pathlib import Path


BASELINE_IDS = {
    "PME-ACC-2025-011",
    "PME-ACC-2025-013",
    "PME-ACC-2025-016",
    "PME-ACC-2025-019",
    "PME-ACC-2025-022",
    "PME-RCA-2025-001",
    "PME-RCA-2025-003",
    "PME-RCA-2025-006",
}

BASELINE_PROTECTED = {
    "PME-ACC-2025-011": ("gross_modeled_warranty_accrual", 371191049, None, "PERIOD-FY2023", "APPROVED", "Elena Park", "USR-ELENA-PARK", "Warranty Finance Director", None, 0, "bearingpoint_warranty_analytics", "PINNED_FY2023"),
    "PME-ACC-2025-013": ("open_known_orders_accrual", 138647226, None, "PERIOD-FY2023", "APPROVED", "Elena Park", "USR-ELENA-PARK", "Warranty Finance Director", "WPS-FY23-OPEN-004", 0, "bearingpoint_warranty_analytics", "PINNED_FY2023"),
    "PME-ACC-2025-016": ("ibnr_accrual", 188719104, 1024, "PERIOD-FY2023", "APPROVED", "Elena Park", "USR-ELENA-PARK", "Warranty Finance Director", "WPS-FY23-IBNR-007", 0, "bearingpoint_warranty_analytics", "PINNED_FY2023"),
    "PME-ACC-2025-019": ("estimation_risk", 43824719, None, "PERIOD-FY2023", "APPROVED", "Elena Park", "USR-ELENA-PARK", "Warranty Finance Director", "WPS-FY23-RISK-011", 0, "bearingpoint_warranty_analytics", "PINNED_FY2023"),
    "PME-ACC-2025-022": ("ibnr_equivalent_repair_orders", None, 1024, "PERIOD-FY2023", "APPROVED", "Elena Park", "USR-ELENA-PARK", "Warranty Finance Director", "WPS-FY23-IBNR-007", 1, "bearingpoint_warranty_analytics", "PINNED_FY2023"),
    "PME-RCA-2025-001": ("modeled_repair_cost_total", 708064087, None, "PERIOD-FY2023", "APPROVED", "Elena Park", "USR-ELENA-PARK", "Warranty Finance Director", "WPS-FY23-MODELED-001", 0, "sap_warranty_cost_ledger", "PINNED_FY2023"),
    "PME-RCA-2025-003": ("average_cost_per_repair_order_rounded", 184296, None, "PERIOD-FY2023", "APPROVED", "Elena Park", "USR-ELENA-PARK", "Warranty Finance Director", "WPS-FY23-MODELED-001", 1, "bearingpoint_warranty_analytics", "PINNED_FY2023"),
    "PME-RCA-2025-006": ("failure_category_report_subtotal", 708064087, 3842, "PERIOD-FY2023", "APPROVED", "Elena Park", "USR-ELENA-PARK", "Warranty Finance Director", "WPS-FY23-MODELED-001", 1, "bearingpoint_warranty_analytics", "PINNED_FY2023"),
}


def _db_path(ws):
    return Path(ws).parent / "system" / "bearingpoint_warranty_analytics" / "state.db"


def _protected(row):
    keys = (
        "metric_name", "metric_value_cents", "metric_value_count", "reporting_period",
        "approval_status", "approved_by", "approved_by_id", "approved_by_role",
        "source_snapshot_id", "presentation_output", "source_system", "dataset_scope",
    )
    return tuple(row[key] for key in keys)


def check_published_extract(ws):
    expected = {
        "metric_name": "modeled_repair_cost_total",
        "metric_value_cents": 708064087,
        "metric_value_count": 3842,
        "reporting_period": "PERIOD-FY2023",
        "approval_status": "APPROVED",
        "approved_by": "Elena Park",
        "approved_by_id": "USR-ELENA-PARK",
        "approved_by_role": "Warranty Finance Director",
        "source_snapshot_id": "WPS-FY23-MODELED-001",
        "presentation_output": 0,
        "source_system": "bearingpoint_warranty_analytics",
        "dataset_scope": "BACKGROUND",
    }
    with sqlite3.connect(_db_path(ws)) as con:
        con.row_factory = sqlite3.Row
        rows = con.execute(
            "SELECT * FROM published_model_extracts "
            "WHERE reporting_period=? AND metric_name=? ORDER BY extract_id",
            ("PERIOD-FY2023", "modeled_repair_cost_total"),
        ).fetchall()
    new_rows = [row for row in rows if row["extract_id"] not in BASELINE_IDS]
    if len(new_rows) != 1:
        return {"score": 0, "detail": f"expected one new FY2023 modeled-total publication, found {len(new_rows)}"}
    row = new_rows[0]
    mismatches = {key: (row[key], value) for key, value in expected.items() if row[key] != value}
    if mismatches:
        return {"score": 0, "detail": f"new publication fields mismatch: {mismatches}"}
    if row["file_name"] == "Warranty Repair Cost Analysis FY2023.xlsx" and row["extract_version"] == "v1.4-approved":
        return {"score": 0, "detail": "publication reused an existing file/version"}
    return {"score": 1, "detail": f"validated new publication {row['extract_id']} ({row['file_name']} / {row['extract_version']})"}


def check_preexisting_publications_unchanged(ws):
    with sqlite3.connect(_db_path(ws)) as con:
        con.row_factory = sqlite3.Row
        rows = con.execute(
            "SELECT * FROM published_model_extracts WHERE extract_id IN (%s)"
            % ",".join("?" for _ in BASELINE_IDS), tuple(sorted(BASELINE_IDS))
        ).fetchall()
    if {row["extract_id"] for row in rows} != BASELINE_IDS:
        return {"score": 0, "detail": "one or more protected pre-existing publications is missing"}
    for row in rows:
        if _protected(row) != BASELINE_PROTECTED[row["extract_id"]]:
            return {"score": 0, "detail": f"protected publication {row['extract_id']} changed"}
    return {"score": 1, "detail": "all protected pre-existing publication rows remain present and approved"}
